<?php
declare(strict_types=1);
namespace Workspace;
require dirname(__DIR__).'/app/bootstrap.php';
$n=0;
function ecCheck(bool $ok,string $label): void {if(!$ok)throw new \RuntimeException($label);++$GLOBALS['n'];}
function ecReject(callable $fn): void {try{$fn();}catch(Problem $e){ecCheck($e->status===409,'wrong failure status');return;}throw new \RuntimeException('Expected rejection');}
foreach(['engine'=>['2.1.0','publish_cas'],'book'=>['1.2.0','snapshot'],'lite'=>['1.6.0','publish_locked'],'forum'=>['1.6.0','personal_acl']] as $type=>[$v,$op]){ecCheck(editorialCapability($type,$v,$op)['version']===$v,'version '.$type);ecReject(fn()=>editorialCapability($type,'999.0.0',$op));ecReject(fn()=>editorialCapability($type,$v,'unknown'));}
$health=['version'=>'2.1.0','edition_version'=>'1.6.0','engine_api_version'=>'1.1'];editorialForumHealth($health);ecCheck(true,'health');ecReject(fn()=>editorialForumHealth(array_replace($health,['engine_api_version'=>'1.2'])));ecReject(fn()=>editorialForumHealth(array_replace($health,['version'=>'2.2.0'])));
$d=editorialTextDiff("a\nb\nc","a\nx\ny\nc");ecCheck(!$d['equal']&&$d['first_line']===2&&$d['removed']===1&&$d['added']===2&&$d['before']==='b'&&$d['after']==="x\ny",'changed range');ecCheck(editorialTextDiff('same','same')['equal'],'same');ecCheck(!editorialTextDiff("a\r\n","a\n")['equal'],'exact bytes');$d=editorialTextDiff(str_repeat('я',10000),str_repeat('ё',10000));ecCheck($d['bounded']&&strlen($d['before'])<=16000&&preg_match('//u',$d['before'])===1,'bounded unicode');ecCheck(editorialTextDiff(str_repeat("a\n",200),'b')['removed']===201,'bounded range');
$t=['thread'=>['title'=>'Title'],'first_post_id'=>'p','posts'=>[['id'=>'p','body'=>'Body','author_id'=>'a']]];ecCheck(editorialThreadMatches($t,'Title','Body','a'),'exact post');ecCheck(!editorialThreadMatches($t,'Title','Changed','a'),'wrong text');ecCheck(!editorialThreadMatches($t,'Title','Body','b'),'wrong actor');$t['posts'][0]['ignored_author']=true;ecCheck(!editorialThreadMatches($t,'Title','Body','a'),'hidden actor');
$a=str_repeat('a',64);$b=str_repeat('b',64);$j=['state'=>'published','expected_hash'=>$a,'after_hash'=>$b,'backup_name'=>'backup','backup_hash'=>$a,'path'=>'/guide'];$page=['title'=>'Guide','body'=>'Content'];$site=['site_hash'=>$b,'inspected_at'=>1000,'catalog'=>json_encode(['/guide'=>$page+['published'=>true]])];ecCheck(editorialLiteObservation($j,$site,$page,1900),'fresh');ecCheck(!editorialLiteObservation($j,$site,$page,1901),'stale');ecCheck(!editorialLiteObservation($j,$site,$page,999),'future');ecCheck(!editorialLiteObservation($j,array_replace($site,['site_hash'=>$a]),$page,1000),'divergent site');ecCheck(!editorialLiteObservation($j,$site,array_replace($page,['body'=>'changed']),1000),'divergent text');ecCheck(editorialLiteRecovery($j,$a)==='aborted','original');ecCheck(editorialLiteRecovery($j,$b)==='published','after');ecCheck(editorialLiteRecovery(array_replace($j,['backup_name'=>null]),$b)==='uncertain','missing backup');ecCheck(editorialLiteRecovery($j,str_repeat('c',64))==='uncertain','third state');
ecCheck(sensitiveAction('editorial.recover'),'MFA');echo "OK · $n проверок редакторских возможностей\n";
